cd /tmp/work/statsmisc && cat > pty2.py <<'PYEOF'
import os, sys, select, subprocess
def run(args, cwd=None, env=None, feed=None):
    mo, so = os.openpty(); me, se = os.openpty(); mi, si = os.openpty()
    e = dict(os.environ); 
    if env: e.update(env)
    p = subprocess.Popen(args, cwd=cwd, stdin=si, stdout=so, stderr=se, env=e)
    os.close(so); os.close(se); os.close(si)
    if feed is not None: os.write(mi, feed)
    out=b''; err=b''; fds=[mo,me]
    while fds:
        r,_,_ = select.select(fds,[],[],5.0)
        if not r: break
        for fd in r:
            try: d=os.read(fd,65536)
            except OSError: d=b''
            if not d: fds.remove(fd); continue
            if fd==mo: out+=d
            else: err+=d
    p.wait(); os.close(mo); os.close(me); os.close(mi)
    return p.returncode,out,err
if __name__=='__main__':
    cwd=sys.argv[1]
    envs={}
    args=sys.argv[2:]
    while args and '=' in args[0] and not args[0].startswith('/'):
        k,v=args[0].split('=',1); envs[k]=v; args=args[1:]
    rc,out,err=run(args,cwd=cwd,env=envs)
    print("RC=",rc); print("STDOUT=",repr(out)); print("STDERR=",repr(err))
